fn guide_of_field_of_fight_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.lines_as(
        "SongHeeYeon",
        args![".....", "Hi, there~", "This is a field of fight.", "Got any questions?"],
    )?;
    ctx.next()?;
    'b1: {
        let subject1 = Val::from(runtime::select_values(
            ctx,
            &[Val::from("A field of fight?:You got a minute lady?:Get in.:Out.:Nope.")],
        )?);
        let mut matched1 = false;
        let no_case1 = !subject1.loosely_equals(&Val::from(1))
            && !subject1.loosely_equals(&Val::from(2))
            && !subject1.loosely_equals(&Val::from(3))
            && !subject1.loosely_equals(&Val::from(4))
            && !subject1.loosely_equals(&Val::from(5));
        if !matched1 && subject1.loosely_equals(&Val::from(1)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as(
                "SongHeeYeon",
                args![
                    "Just like the name of this place,",
                    "it is a field for matches.",
                    "We have various monsters",
                    "in different levels."
                ],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "SongHeeYeon",
                args![
                    "1st Class Boss Monsters are in middle of preparation yet.",
                    "We charge you a small fee to enter here."
                ],
            )?;
            break 'b1;
        }
        if !matched1 && subject1.loosely_equals(&Val::from(2)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as(
                "SongHeeYeon",
                args!["Eh.... excuse me?", "Ah, I'm afraid I have to work right now...", "Sorry..."],
            )?;
            break 'b1;
        }
        if !matched1 && subject1.loosely_equals(&Val::from(3)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as("SongHeeYeon", args!["Yes, thank you.", "Have a good time."])?;
            ctx.close_window()?;
            ctx.var("in_battle").set(Val::from(3))?;
            ctx.call(Function::Warp, vec![Val::from("gon_test"), Val::from(25), Val::from(98)])?;
            return Err(Stop::End);
        }
        if !matched1 && subject1.loosely_equals(&Val::from(4)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as("SongHeeYeon", args!["Thank you.", "Please come again."])?;
            ctx.close_window()?;
            ctx.call(Function::Warp, vec![Val::from("gonryun"), Val::from(177), Val::from(112)])?;
            return Err(Stop::End);
        }
        if !matched1 && subject1.loosely_equals(&Val::from(5)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as("SongHeeYeon", args!["........", "Goodbye..."])?;
            break 'b1;
        }
    }
    ctx.close_window()?;
    return Err(Stop::End);
}

pub fn guide_of_field_of_fight(ctx: &Ctx) -> Script {
    guide_of_field_of_fight_body(ctx, Vec::new()).map(|_| ())
}

fn chowanan_gnp_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.lines_as("ChowAnAn", args!["Want to go back?"])?;
    ctx.next()?;
    if Val::from(runtime::select_values(ctx, &[Val::from("Yes.:No.")])?) == 1 {
        ctx.lines_as("ChowAnAn", args!["Thank you.", "Please come again."])?;
        ctx.close_window()?;
        ctx.var("in_battle").set(Val::from(1))?;
        ctx.call(Function::Warp, vec![Val::from("gon_test"), Val::from(44), Val::from(4)])?;
        return Err(Stop::End);
    }
    ctx.lines_as("ChowAnAn", args!["Thank you."])?;
    ctx.close_window()?;
    return Err(Stop::End);
}

pub fn chowanan_gnp(ctx: &Ctx) -> Script {
    chowanan_gnp_body(ctx, Vec::new()).map(|_| ())
}
